#include <iostream>
#include <vector>

int main() {
    uint64_t p, k;
    std::cin >> p >> k;

    const uint64_t MOD = 1000000007;

    auto fastExponentiation = [&](uint64_t base, uint64_t exp) {
        uint64_t result = 1;
        uint64_t b = base % MOD;
        while (exp > 0) {
            if (exp & 1) result = (result * b) % MOD;
            b = (b * b) % MOD;
            exp >>= 1;
        }
        return result;
    };

    if (k == 0) {
        std::cout << fastExponentiation(p, p - 1) << std::endl;
        return 0;
    }
    if (k == 1) {
        std::cout << fastExponentiation(p, p) << std::endl;
        return 0;
    }

    std::vector<bool> visited(p + 1, false);
    uint64_t total = 1;

    for (uint64_t x = 1; x < p; ++x) {
        if (visited[x]) continue;
        total = (total * p) % MOD;
        uint64_t v = x;
        while (!visited[(v * k) % p]) {
            visited[(v * k) % p] = true;
            v = (v * k) % p;
        }
    }
    std::cout << total << std::endl;
    return 0;
}
