import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long p = scanner.nextLong();
        long k = scanner.nextLong();

        final long MOD = 1000000007;

        // Fast exponentiation method
        long fastExponentiation(long base, long exp) {
            long result = 1;
            long b = base % MOD;
            while (exp > 0) {
                if ((exp & 1) == 1) {
                    result = (result * b) % MOD;
                }
                b = (b * b) % MOD;
                exp >>= 1;
            }
            return result;
        }

        if (k == 0) {
            System.out.println(fastExponentiation(p, p - 1));
            return;
        }
        if (k == 1) {
            System.out.println(fastExponentiation(p, p));
            return;
        }

        boolean[] visited = new boolean[(int) p + 1];
        long total = 1;

        for (long x = 1; x < p; ++x) {
            if (visited[(int) x]) continue;
            total = (total * p) % MOD;
            long v = x;
            while (!visited[(int) ((v * k) % p)]) {
                visited[(int) ((v * k) % p)] = true;
                v = (v * k) % p;
            }
        }
        System.out.println(total);
    }
}
